import{_ as i,B as s,o as t,c as d,ax as a,b as n,w as o,a as l,E as c,ah as h}from"./chunks/framework.Bnt0oLax.js";const w=JSON.parse(`{"title":"Scripts Overview","description":"How global scripts work — where they run, how they're injected, and how they compare to widgets","frontmatter":{"description":"How global scripts work — where they run, how they're injected, and how they compare to widgets"},"headers":[],"relativePath":"custom-widgets/v2/scripts-overview.md","filePath":"custom-widgets/v2/scripts-overview.md"}`),p={name:"custom-widgets/v2/scripts-overview.md"};function g(u,e,f,m,y,b){const r=s("Mermaid");return t(),d("div",null,[e[1]||(e[1]=a('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /docs/custom-widgets/v2/scripts-overview.md for this page in Markdown format</div><h1 id="scripts-overview" tabindex="-1">Scripts Overview <a class="header-anchor" href="#scripts-overview" aria-label="Permalink to &quot;Scripts Overview&quot;">​</a></h1><p>Scripts are JavaScript files that run across your community pages, independent of individual widgets. Use them for analytics, tracking, shared utilities, or any page-level behavior that applies globally instead of to one widget at a time.</p><h2 id="how-scripts-work" tabindex="-1">How Scripts Work <a class="header-anchor" href="#how-scripts-work" aria-label="Permalink to &quot;How Scripts Work&quot;">​</a></h2><p>Each script you declare in the <code>scripts</code> array of <code>extensions_registry.json</code> becomes a <code>&lt;script&gt;</code> tag injected into every matching page of your community. The platform publishes the file from your repository (or loads it from an external URL) and inserts the tag at the location you choose.</p>',5)),(t(),n(h,null,{default:o(()=>[c(r,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5B%22scripts%2Fanalytics%2Fscript.js%22%5D%20--%3E%20B%5B%22Published%20by%20platform%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22Script%20tag%20injected%20on%20page%20load%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Code%20runs%20in%20the%20page%22%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23eef5fc%2Cstroke%3A%2339a2ff%2Ccolor%3A%23132436%0A%20%20%20%20style%20B%20fill%3A%23dbeafe%2Cstroke%3A%233b82f6%2Ccolor%3A%231e293b%0A%20%20%20%20style%20C%20fill%3A%23dbeafe%2Cstroke%3A%233b82f6%2Ccolor%3A%231e293b%0A%20%20%20%20style%20D%20fill%3A%23dcfce7%2Cstroke%3A%2322c55e%2Ccolor%3A%231e293b%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<h2 id="scripts-vs-widgets" tabindex="-1">Scripts vs Widgets <a class="header-anchor" href="#scripts-vs-widgets" aria-label="Permalink to &quot;Scripts vs Widgets&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aspect</th><th>Widget</th><th>Script</th></tr></thead><tbody><tr><td>Scope</td><td>One component in one page zone</td><td>The whole page, every matching page</td></tr><tr><td>Placement</td><td>Chosen in the No-Code Builder</td><td>Declared via <code>placement</code> field</td></tr><tr><td>Isolation</td><td>Shadow DOM</td><td>Runs directly on the page</td></tr><tr><td>Configuration</td><td>Per-instance via No-Code Builder</td><td>Same for every page that loads it</td></tr><tr><td>Use cases</td><td>Interactive UI, forms, dashboards</td><td>Analytics, tracking, shared utilities</td></tr></tbody></table><p>Widgets exist to give community admins something to place and configure. Scripts exist to run page-level code that doesn&#39;t belong to any single widget.</p><h2 id="where-scripts-run" tabindex="-1">Where Scripts Run <a class="header-anchor" href="#where-scripts-run" aria-label="Permalink to &quot;Where Scripts Run&quot;">​</a></h2><p>Scripts are injected at one of three locations, controlled by the <code>placement</code> field:</p><table tabindex="0"><thead><tr><th>Placement</th><th>Location</th><th>Use case</th></tr></thead><tbody><tr><td><code>head</code> (default)</td><td>Inside <code>&lt;head&gt;</code></td><td>Analytics, early initialization, scripts that need to run before content renders</td></tr><tr><td><code>bodyStart</code></td><td>Start of <code>&lt;body&gt;</code></td><td>Scripts that need the DOM to start loading but should run early</td></tr><tr><td><code>bodyEnd</code></td><td>End of <code>&lt;body&gt;</code></td><td>Non-critical scripts that depend on page content being fully loaded</td></tr></tbody></table><h2 id="repository-hosted-vs-external" tabindex="-1">Repository-Hosted vs External <a class="header-anchor" href="#repository-hosted-vs-external" aria-label="Permalink to &quot;Repository-Hosted vs External&quot;">​</a></h2><p>Each script has a <code>path</code> field. Two shapes are supported:</p><ul><li><strong>Repository path</strong> (e.g. <code>scripts/analytics/script.js</code>) — the file lives in your repository and the platform publishes it.</li><li><strong>External URL</strong> (e.g. <code>https://cdn.example.com/tracker.js</code>) — the tag loads directly from that URL. The platform does not fetch or publish it.</li></ul><h2 id="conditional-loading" tabindex="-1">Conditional Loading <a class="header-anchor" href="#conditional-loading" aria-label="Permalink to &quot;Conditional Loading&quot;">​</a></h2><p>By default, a script loads on every page of your community. Use the <code>rules</code> field to load a script only when the current page matches conditions like a specific page type, locale, or authenticated user. See <a href="./page-targeting.html">Page Targeting</a> for the full rule language.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="./first-script.html">Your First Script</a> — hands-on tutorial from scratch to published script</li><li><a href="./scripts.html">Script Definition Reference</a> — every field and option</li><li><a href="./page-targeting.html">Page Targeting</a> — conditional loading rules</li><li><a href="./registry-reference.html">Registry Reference</a> — where scripts fit in the registry file</li></ul>',13))])}const S=i(p,[["render",g]]);export{w as __pageData,S as default};
